/** The harness an agent belongs to: an added agent's id is its harness's, then `~` and its own. */
export function harnessOf(agentId: string): string {
  const tilde = agentId.indexOf('~')
  return tilde < 0 ? agentId : agentId.slice(0, tilde)
}

export function markFor(agentId: string): Mark | null {
  return MARKS[harnessOf(agentId)] ?? null
}

/** The color that stands for an agent in charts: its brand's, else a series slot by its order. */
export function agentColor(agentId: string, fallback: string): string {
  switch (harnessOf(agentId)) {
    case 'claude-code':
      return brand.claude
    case 'codex':
      return brand.codex[1]
    case 'gemini':
      return brand.gemini[0]
    case 'deepseek':
      return brand.deepseek
    case 'qwen':
      return brand.qwen
    case 'kimi':
      return brand.kimi
    case 'pi':
      return brand.piBlue
    default:
      return fallback
  }
}
